import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
using namespace cute;
template <typename T>
__device__ __forceinline__ void load_conv_tile(
    const T* __restrict__ X, const T* __restrict__ W,
    float* __restrict__ sX, float* __restrict__ sW,
    int cin, int n, int co_base, int tid, int Threads,
    int tile_elems, int wt_elems, int H_in_tile, int W_in_tile,
    int ih_base, int iw_base, int H, int Win, int Cout, int Kh, int Kw,
    int64_t sXn, int64_t sXc, int64_t sWco, int64_t sWcin)
{
  const T* Xc = X + (int64_t)n * sXn + (int64_t)cin * sXc;
  for (int idx = tid; idx < tile_elems; idx += Threads) {
    int r = idx / W_in_tile;
    int c = idx - r * W_in_tile;
    int ih = ih_base + r;
    int iw = iw_base + c;
    float val = 0.0f;
    if ((unsigned)ih < (unsigned)H && (unsigned)iw < (unsigned)Win) {
      val = (float)Xc[(int64_t)ih * Win + iw];
    }
    sX[idx] = val;
  }
  for (int idx = tid; idx < wt_elems; idx += Threads) {
    int cc  = idx / (Kh * Kw);
    int rem = idx - cc * (Kh * Kw);
    int co  = co_base + cc;
    float wval = 0.0f;
    if (co < Cout) {
      wval = (float)W[(int64_t)co * sWco + (int64_t)cin * sWcin + rem];
    }
    sW[idx] = wval;
  }
}
template <typename T>
__global__ void conv2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bp,
    T* __restrict__ Y,
    int N, int Cin, int H, int Win,
    int Cout, int Kh, int Kw,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int Hout, int Wout,
    int H_in_tile, int W_in_tile,
    int num_co_tiles)
{
  constexpr int TILE_OH    = 16;
  constexpr int TILE_OW    = 16;
  constexpr int OW_PER_THREAD = 4;
  constexpr int CoPerBlock = 16;
  constexpr int Threads    = TILE_OH * TILE_OW;
  const int tid = threadIdx.y * TILE_OW + threadIdx.x;
  const int ow_base = blockIdx.x * TILE_OW * OW_PER_THREAD;
  const int oh_base = blockIdx.y * TILE_OH;
  const int n       = blockIdx.z / num_co_tiles;
  const int co_tile = blockIdx.z % num_co_tiles;
  const int co_base = co_tile * CoPerBlock;
  const int oh_local = threadIdx.y;
  const int ow_local = threadIdx.x;
  const int oh = oh_base + oh_local;
  int ow[OW_PER_THREAD];
  #pragma unroll
  for (int j = 0; j < OW_PER_THREAD; ++j) {
    ow[j] = ow_base + ow_local + j * TILE_OW;
  }
  const int ih_base = oh_base * stride_h - pad_h;
  const int iw_base = ow_base * stride_w - pad_w;
  const int64_t sXn  = (int64_t)Cin * H * Win;
  const int64_t sXc  = (int64_t)H * Win;
  const int64_t sYn  = (int64_t)Cout * Hout * Wout;
  const int64_t sYc  = (int64_t)Hout * Wout;
  const int64_t sWco  = (int64_t)Cin * Kh * Kw;
  const int64_t sWcin = (int64_t)Kh * Kw;
  const int tile_elems = H_in_tile * W_in_tile;
  const int wt_elems   = CoPerBlock * Kh * Kw;
  extern __shared__ float smem[];
  float* sXbuf[2];
  float* sWbuf[2];
  sXbuf[0] = smem;
  sWbuf[0] = smem + tile_elems;
  sXbuf[1] = smem + tile_elems + wt_elems;
  sWbuf[1] = sXbuf[1] + tile_elems;
  float acc[CoPerBlock][OW_PER_THREAD];
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    float bval = (Bp != nullptr && co < Cout) ? (float)Bp[co] : 0.0f;
    #pragma unroll
    for (int j = 0; j < OW_PER_THREAD; ++j) {
      acc[cc][j] = bval;
    }
  }
  const bool row_valid = (oh < Hout);
  bool valid[OW_PER_THREAD];
  #pragma unroll
  for (int j = 0; j < OW_PER_THREAD; ++j) {
    valid[j] = row_valid && (ow[j] < Wout);
  }
  int cur = 0;
  load_conv_tile<T>(X, W, sXbuf[0], sWbuf[0], 0, n, co_base, tid, Threads,
                     tile_elems, wt_elems, H_in_tile, W_in_tile,
                     ih_base, iw_base, H, Win, Cout, Kh, Kw,
                     sXn, sXc, sWco, sWcin);
  __syncthreads();
  for (int cin = 0; cin < Cin; ++cin) {
    int next = cur ^ 1;
    if (cin + 1 < Cin) {
      load_conv_tile<T>(X, W, sXbuf[next], sWbuf[next], cin + 1, n, co_base, tid, Threads,
                         tile_elems, wt_elems, H_in_tile, W_in_tile,
                         ih_base, iw_base, H, Win, Cout, Kh, Kw,
                         sXn, sXc, sWco, sWcin);
    }
    float* sX = sXbuf[cur];
    float* sW = sWbuf[cur];
    if (row_valid) {
      for (int kh = 0; kh < Kh; ++kh) {
        int local_ih = oh_local * stride_h + kh * dil_h;
        const float* sXrow = sX + local_ih * W_in_tile;
        for (int kw = 0; kw < Kw; ++kw) {
          int local_iw0 = ow_local * stride_w + kw * dil_w;
          float xval[OW_PER_THREAD];
          #pragma unroll
          for (int j = 0; j < OW_PER_THREAD; ++j) {
            xval[j] = sXrow[local_iw0 + j * TILE_OW * stride_w];
          }
          #pragma unroll
          for (int cc = 0; cc < CoPerBlock; ++cc) {
            float wval = sW[cc * Kh * Kw + kh * Kw + kw];
            #pragma unroll
            for (int j = 0; j < OW_PER_THREAD; ++j) {
              acc[cc][j] += xval[j] * wval;
            }
          }
        }
      }
    }
    __syncthreads();
    cur = next;
  }
  #pragma unroll
  for (int cc = 0; cc < CoPerBlock; ++cc) {
    int co = co_base + cc;
    if (co < Cout) {
      #pragma unroll
      for (int j = 0; j < OW_PER_THREAD; ++j) {
        if (valid[j]) {
          Y[(int64_t)n * sYn + (int64_t)co * sYc + (int64_t)oh * Wout + ow[j]] = static_cast<T>(acc[cc][j]);
        }
      }
    }
  }
}
torch::Tensor conv2d_forward(torch::Tensor x,
                              torch::Tensor w,
                              c10::optional<torch::Tensor> b,
                              int stride_h, int stride_w,
                              int pad_h, int pad_w,
                              int dil_h, int dil_w) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");
  TORCH_CHECK(x.dim() == 4, "x must be [N, Cin, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [Cout, Cin, Kh, Kw]");
  int64_t N    = x.size(0);
  int64_t Cin  = x.size(1);
  int64_t H    = x.size(2);
  int64_t Win  = x.size(3);
  int64_t Cout = w.size(0);
  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1 only)");
  int64_t Kh = w.size(2);
  int64_t Kw = w.size(3);
  TORCH_CHECK(stride_h > 0 && stride_w > 0, "stride must be > 0");
  TORCH_CHECK(pad_h >= 0 && pad_w >= 0, "padding must be >= 0");
  TORCH_CHECK(dil_h > 0 && dil_w > 0, "dilation must be > 0");
  int64_t Hout = (H + 2 * pad_h - dil_h * (Kh - 1) - 1) / stride_h + 1;
  int64_t Wout = (Win + 2 * pad_w - dil_w * (Kw - 1) - 1) / stride_w + 1;
  TORCH_CHECK(Hout > 0 && Wout > 0, "Invalid output size computed");
  auto x_c = x.contiguous();
  auto w_c = w.contiguous();
  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == Cout, "bias must be [Cout]");
    b_ptr = b_c.data_ptr<float>();
  }
  auto y = torch::empty({N, Cout, Hout, Wout}, x.options());
  constexpr int TILE_OH    = 16;
  constexpr int TILE_OW    = 16;
  constexpr int OW_PER_THREAD = 4;
  constexpr int CoPerBlock = 16;
  const int H_in_tile = (int)((TILE_OH - 1) * stride_h + (Kh - 1) * dil_h + 1);
  const int W_in_tile = (int)((TILE_OW * OW_PER_THREAD - 1) * stride_w + (Kw - 1) * dil_w + 1);
  const int num_ow_tiles = (int)((Wout + (TILE_OW * OW_PER_THREAD) - 1) / (TILE_OW * OW_PER_THREAD));
  const int num_oh_tiles = (int)((Hout + TILE_OH - 1) / TILE_OH);
  const int num_co_tiles = (int)((Cout + CoPerBlock - 1) / CoPerBlock);
  dim3 block(TILE_OW, TILE_OH);
  dim3 grid(
      (unsigned)num_ow_tiles,
      (unsigned)num_oh_tiles,
      (unsigned)(N * num_co_tiles)
  );
  size_t shared_bytes = (size_t)(H_in_tile * W_in_tile + CoPerBlock * (int)Kh * (int)Kw) * sizeof(float) * 2;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  if (shared_bytes > 48 * 1024) {
    cudaFuncSetAttribute(conv2d_kernel<float>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)shared_bytes);
  }
  conv2d_kernel<float><<<grid, block, shared_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)H, (int)Win,
      (int)Cout, (int)Kh, (int)Kw,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      (int)Hout, (int)Wout,
      H_in_tile, W_in_tile,
      num_co_tiles
  );
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv2d_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
"""

conv2d_ext = load_inline(
    name="cute_conv2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 2D convolution with square input and asymmetric kernel,
    with dilation and padding, implemented with a custom CUDA kernel using CuTe.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: int = 1, padding: tuple = (0, 0), dilation: tuple = (1, 1),
                 bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = kernel_size
        self.stride = int(stride)
        self.padding = padding
        self.dilation = dilation

        kh, kw = kernel_size
        self.weight = nn.Parameter(torch.empty(out_channels, in_channels, kh, kw))
        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            kh, kw = self.kernel_size
            fan_in = self.in_channels * kh * kw
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        pad_h, pad_w = self.padding
        dil_h, dil_w = self.dilation
        return self._ext.conv2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            self.stride, self.stride,
            pad_h, pad_w,
            dil_h, dil_w,
        )

